/usr/share/polkit-1/rules.d/org.projecta.text:
polkit.addRule(function(action, subject) {
    if ((action.id == "org.projectatomic.rpmostree1.repo-refresh" ||
         action.id == "org.projectatomic.rpmostree1.upgrade") &&
        subject.active == true &&
        subject.local == true) {
            return polkit.Result.YES;
    }

    if ((action.id == "org.projectatomic.rpmostree1.install-uninstall-packages" ||
         action.id == "org.projectatomic.rpmostree1.rollback" ||
         action.id == "org.projectatomic.rpmostree1.reload-daemon" ||
         action.id == "org.projectatomic.rpmostree1.cancel" ||
         action.id == "org.projectatomic.rpmostree1.cleanup" ||
         action.id == "org.projectatomic.rpmostree1.client-management") &&
        subject.active == true &&
        subject.local == true &&
        subject.isInGroup("wheel")) {
            return polkit.Result.YES;
    }
});

/usr/share/polkit-1/rules.d/20-privilege.text:
polkit.addRule(function(action, subject) {
    if ((action.id == "org.bazzite.policykit.privileged.user.setup") &&
         subject.isInGroup("wheel")) {
        return polkit.Result.YES;
    }
});

/usr/share/polkit-1/rules.d/empower.rule.text:
// Allow all actions for users who are in the "empower" group. Users are added to the
// "empower" group by running run0 --empower.

polkit.addRule(function(action, subject) {
    if (subject.isInGroup("empower")) {
        return polkit.Result.YES;
    }
});
